            <p class="text-sm text-dark mb-4">Step 3 of 4</p>

            <div class="w-full bg-lightblue border-b-2 border-dark p-2">
              <label for="signup-password" class="leading-tight text-dark">Password</label>
              <input
                id="signup-password"
                v-model="password"
                class="w-full bg-lightblue text-lg"
                :type="`${revealPassword ? 'text' : 'password'}`"
                autocomplete="new-password"
              />
            </div>

            <div class="w-full bg-lightblue border-b-2 border-dark p-2 mt-4">
              <label for="signup-password-confirm" class="leading-tight text-dark">Confirm password</label>
              <input
                id="signup-password-confirm"
                v-model="passwordConfirm"
                class="w-full bg-lightblue text-lg"
                :type="`${revealPassword ? 'text' : 'password'}`"
                autocomplete="new-password"
              />
            </div>

            <p
              v-if="password && passwordConfirm && password !== passwordConfirm"
              class="mt-2 text-red-600 text-sm font-medium"
              role="alert"
            >
              Passwords do not match.
            </p>

            <PasswordRules :password="password" />

            <button
              type="button"
              @click="revealPassword = !revealPassword"
              class="text-blue pl-2 mt-2"
              :aria-pressed="revealPassword"
            >
              <i :class="revealPassword ? 'fas fa-eye-slash' : 'fas fa-eye'" aria-hidden="true"></i>
              {{ revealPassword ? "Hide password" : "Reveal password" }}
            </button>
          </div>
        </div>

        <div v-if="showModal === 'step4'">
          <div class="pl-1 pr-4 py-1 h-12">
            <button
              @click="setSignUpStep('step3')"
              class="absolute rounded-full p-2 pl-3 hover:bg-lightblue"
              aria-label="Back"
            >
              <i class="fas fa-arrow-left text-blue"></i>
            </button>
            <p class="flex items-start ml-12 p-2 text-sm text-dark">
              Step 4 of 4
            </p>
          </div>
          <div class="pt-5 px-8">
            <div class="flex justify-between items-center pb-8">
              <p class="text-2xl font-bold">Create your account</p>
            </div>

            <p>
              By signing up, you agree to our
              <a href="https://github.com/Warp-net/docs/blob/main/legal/T%26C.md" target="_blank" rel="noopener" class="text-blue">Terms</a>
              and
              <a href="https://github.com/Warp-net/docs/blob/main/legal/PRIVACY-POLICY.md" target="_blank" rel="noopener" class="text-blue">Privacy Policy</a>.
            </p>
            <button
              v-if="!isLoading"
              @click="signMeUp"
              class="w-full rounded-full mt-4 py-3 bg-blue text-white font-bold hover:bg-darkblue"
            >
              Sign up
            </button>
            <div v-else class="w-full rounded-full mt-4 py-3">
              <ProgressBar/>
            </div>
            <p v-if="signUpError" class="mt-3 text-red-600 text-sm text-center font-medium" role="alert">
